<template>
<view :data-skin="scenicSkin" class="visual-page town-page">
 <header class="town-header"><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" @click="home">‹ 首页</button><view><text class="eyebrow">QINGYA MOUNTAIN / 常驻营地</text><text class="town-title">青崖山 · 人间正在重建</text></view><SkinSwitch/></header>
 <view class="town-layout">
  <view class="map-panel">
   <view class="map-heading"><text>景区导览</text><text>{{unlocked?'点击地点，与这里的人说说话':'抵达 EP13 青崖山后开启营地互动'}}</text></view>
   <view class="map-world">
    <view class="waterway"/><view class="trail trail-one"/><view class="trail trail-two"/><text class="map-water-label">青 崖 水 库</text>
    <button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" v-for="p in townPlaces" :key="p.id" class="map-place" :class="{locked:!townAvailable(s,p),selected:selected?.id===p.id}" :style="{left:p.x+'%',top:p.y+'%'}" :aria-label="p.name+' '+status(p)" @click="select(p)"><TownSprite :name="p.sprite"/><text class="pin">{{!townAvailable(s,p)?'锁':townResult(s,p)?'✓':p.id==='visitor'?'!':'···'}}</text><text class="place-name">{{p.name}}</text></button>
    <view class="walker"><TownSprite name="walker"/></view><text class="compass">北 ↑<br/>N</text>
   </view>
   <view class="map-caption"><text>已开放 {{openCount}} / 7 处</text><text>● 可交谈　✓ 已记录　锁 待开放</text></view>
  </view>
  <view class="town-sidebar">
   <text class="eyebrow">CAMP JOURNAL / 今日营地</text><text class="section-title">每一盏灯后，都有人。</text><text class="sidebar-copy">先听听他们的需要。一次问候、一次安排，也会成为景区的一部分。</text>
   <view class="town-resources"><view v-for="r in resources" :key="r.id"><text>{{r.name}}</text><b>{{s.stats[r.id]}}</b></view></view>
   <AssetButton @click="continueStory">{{s.hasSave?'继续主线 · '+node.title:'从考场开始旅程'}}　›</AssetButton>
   <view class="place-list"><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" v-for="p in townPlaces" :key="p.id" @click="select(p)"><text>{{p.name}}<small>{{p.role}}</small></text><text>{{status(p)}} ›</text></button></view>
   <text class="town-note">地图对话自动保存，每项安排本周目结算一次。主线进度不会因闲聊改变。</text>
  </view>
 </view>
 <view v-if="selected" class="dialogue-backdrop" @click.self="close">
  <view class="dialogue-card" role="dialog" aria-modal="true" :aria-label="selected.name+'对话'">
   <button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" class="close-dialogue" @click="close">返回地图 ×</button>
   <view class="dialogue-art"><TownSprite name="portrait"/><text>许知微 / 青崖山建设者</text></view>
   <view class="dialogue-content"><text class="eyebrow">{{selected.name}} / {{selected.role}}</text><text class="speaker">{{result?'营地手记':step===1?'许知微':selected.npc}}</text>
    <template v-if="!townAvailable(s,selected)"><text class="speech">{{selected.id==='cable'?'索道尚未完成安全检查，暂不开放。':'随着主线抵达 EP'+selected.episode+'，这里的人与故事将向你开放。'}}</text><AssetButton @click="close">回到地图</AssetButton></template>
    <template v-else-if="result"><text class="speech">{{result.reply}}</text><text class="reward">已记录 · {{rewardText(result)}} · 本周目不重复获得</text><AssetButton @click="close">收起手记，返回营地</AssetButton><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" v-if="selected.id==='visitor'" class="plain" @click="continueStory">继续主线 ›</button></template>
    <template v-else><text class="speech">{{step===0?selected.intro:'许知微：先把眼前能做的事安排好。'}}</text><AssetButton v-if="step===0" @click="step=1">回应 {{selected.npc}}　›</AssetButton><template v-else><button role="button" tabindex="0" @keydown.enter.prevent="activateFocused" @keydown.space.prevent="activateFocused" class="town-choice" v-for="(c,i) in selected.choices" :key="i" @click="choose(i)"><text>{{c.text}}</text><small>{{rewardText(c)}}</small></button></template></template>
   </view>
  </view>
 </view>
</view>
</template>
<script setup lang="ts">
import {activateFocused} from '../../utils/keyboard';import {computed,ref} from 'vue';import {gameStore,storyEngine} from '../../store/game';import {townPlaces,townAvailable,townUnlocked,townResult,chooseTown,type TownPlace,type TownChoice} from '../../data/town';import {resources} from '../../data/scenic-progress';import TownSprite from '../../components/common/TownSprite.vue';import AssetButton from '../../components/common/AssetButton.vue';import SkinSwitch from '../../components/common/SkinSwitch.vue';
const s=gameStore.state,selected=ref<TownPlace>(),step=ref(0),unlocked=computed(()=>townUnlocked(s)),node=computed(()=>storyEngine.getNode()),openCount=computed(()=>townPlaces.filter(p=>townAvailable(s,p)).length),result=computed(()=>selected.value?townResult(s,selected.value):undefined);
function status(p:TownPlace){return !townAvailable(s,p)?'待开放':townResult(s,p)?'已记录':'可交谈'}
function select(p:TownPlace){selected.value=p;step.value=0}function close(){selected.value=undefined}
function rewardText(c:TownChoice){return Object.entries(c.add).map(([k,v])=>(resources.find(r=>r.id===k)?.name||k)+' +'+v).join(' / ')}
function choose(i:number){if(selected.value)chooseTown(s,selected.value.id,i,gameStore.persist)}
function continueStory(){if(!s.hasSave)storyEngine.startNewGame();uni.redirectTo({url:'/pages/play/index'})}function home(){uni.reLaunch({url:'/pages/home/index'})}
</script>
