er;padding:24px;backdrop-filter:blur(5px)}.dialogue-card{position:relative;width:min(850px,100%);max-height:90svh;overflow:auto;display:grid;grid-template-columns:240px 1fr;background:var(--panel);border:1px solid var(--gold);box-shadow:0 20px 80px #0008;padding:58px 30px 30px;box-sizing:border-box;gap:30px}.close-dialogue{position:absolute;top:10px;right:14px;min-height:44px;background:transparent;color:var(--text);font-size:12px}.dialogue-art{align-self:end}.dialogue-art>text{display:block;text-align:center;font-size:11px;color:var(--muted);padding-top:12px}.speaker{display:block;font-size:27px;margin:14px 0}.speech{display:block;font-size:17px;line-height:2;margin-bottom:22px;white-space:pre-line}.reward{display:block;color:var(--gold);font-size:12px;line-height:1.8;margin:18px 0}.town-choice{width:100%;text-align:left;background:var(--panel-2);border:1px solid var(--line);border-radius:0;margin:12px 0;padding:16px;color:var(--text);font:15px/1.7 serif}.town-choice:hover{border-color:var(--gold)}@keyframes stroll{from{transform:translate(-28px,0)}to{transform:translate(35px,13px)}}@media(orientation:portrait){.town-page{padding:18px 14px}.town-header{gap:10px;flex-wrap:wrap}.town-title{font-size:19px}.town-layout{grid-template-columns:1fr}.map-world{height:490px}.map-place{width:76px;height:100px}.place-name{font-size:11px;padding:5px 7px}.map-heading{font-size:9px}.town-sidebar{padding:4px 8px}.dialogue-backdrop{padding:12px}.dialogue-card{grid-template-columns:1fr;padding:58px 22px 24px;gap:10px}.dialogue-art{display:flex;gap:16px;align-items:center;align-self:auto}.dialogue-art .town-sprite{width:65px;flex-shrink:0}.dialogue-art>text{text-align:left}.speech{font-size:16px}.town-header .eyebrow{font-size:8px}}@media(orientation:landscape) and (max-height:600px){.map-world{height:460px}.dialogue-card{max-height:94svh;grid-template-columns:135px 1fr;padding-top:50px}.town-layout{grid-template-columns:minmax(0,1fr) 260px}.map-place{width:85px;height:110px}}@media(